/// <reference types="vite/client" />

declare module '*.css' {
  const css: string;
  export default css;
}

declare module '*.png' {
  const png: string;
  export default png;
}

declare module '*.svg' {
  const svg: string;
  export default svg;
}

declare module '*.jpg' {
  const jpg: string;
  export default jpg;
}

declare module '*.gif' {
  const gif: string;
  export default gif;
}
